/**
 * JavaScript wrapper for Audio Index WASM module
 * Provides a clean API for using the C++ library in the browser
 */

class AudioIndexWASM {
    constructor() {
        this.module = null;
        this.initialized = false;
    }

    /**
     * Initialize the WASM module
     * @returns {Promise<void>}
     */
    async initialize() {
        if (this.initialized) {
            return;
        }

        console.log('Loading Audio Index WASM module...');
        
        try {
            // Load the module (generated by Emscripten)
            const createModule = await import('./audio-index.js');
            this.module = await createModule.default();
            
            this.initialized = true;
            console.log('✓ Audio Index WASM module loaded');
        } catch (error) {
            console.error('Failed to load WASM module:', error);
            throw error;
        }
    }

    /**
     * Ensure module is initialized before use
     * @private
     */
    _ensureInitialized() {
        if (!this.initialized) {
            throw new Error('WASM module not initialized. Call initialize() first.');
        }
    }

    /**
     * Get metadata from a base64 index
     * @param {string} base64Index - URL-safe base64 index
     * @returns {object} Metadata object with genre, artist, album, track, cover
     */
    getMetadata(base64Index) {
        this._ensureInitialized();

        try {
            // Call C++ function
            const resultPtr = this.module._getMetadataFromBase64(
                this.module.allocateUTF8(base64Index)
            );

            // Convert C string to JavaScript string
            const jsonStr = this.module.UTF8ToString(resultPtr);
            
            // Free the C string
            this.module._free(resultPtr);

            // Parse JSON
            const metadata = JSON.parse(jsonStr);

            if (metadata.error) {
                throw new Error(metadata.error);
            }

            return metadata;
        } catch (error) {
            console.error('Error getting metadata:', error);
            throw error;
        }
    }

    /**
     * Reconstruct audio from a base64 index
     * @param {string} base64Index - URL-safe base64 index
     * @returns {Uint8Array} Audio sample data
     */
    reconstructAudio(base64Index) {
        this._ensureInitialized();

        try {
            // Allocate output length variable
            const lengthPtr = this.module._malloc(4);

            // Call C++ function
            const dataPtr = this.module._reconstructAudioFromBase64(
                this.module.allocateUTF8(base64Index),
                lengthPtr
            );

            // Get the length
            const length = this.module.getValue(lengthPtr, 'i32');
            this.module._free(lengthPtr);

            if (length === 0 || !dataPtr) {
                throw new Error('Failed to reconstruct audio');
            }

            // Copy data to JavaScript array
            const audioData = new Uint8Array(length);
            audioData.set(this.module.HEAPU8.subarray(dataPtr, dataPtr + length));

            // Free the C memory
            this.module._free(dataPtr);

            return audioData;
        } catch (error) {
            console.error('Error reconstructing audio:', error);
            throw error;
        }
    }

    /**
     * Generate a random base64 index for exploration
     * @param {number} length - Target length of the index
     * @returns {string} Random base64 index
     */
    generateRandomIndex(length = 100) {
        this._ensureInitialized();

        try {
            const resultPtr = this.module._generateRandomIndex(length);
            const index = this.module.UTF8ToString(resultPtr);
            this.module._free(resultPtr);
            return index;
        } catch (error) {
            console.error('Error generating random index:', error);
            throw error;
        }
    }

    /**
     * Validate a base64 index string
     * @param {string} base64Index - Index to validate
     * @returns {boolean} True if valid
     */
    validateIndex(base64Index) {
        this._ensureInitialized();

        try {
            const isValid = this.module._validateBase64Index(
                this.module.allocateUTF8(base64Index)
            );
            return isValid === 1;
        } catch (error) {
            console.error('Error validating index:', error);
            return false;
        }
    }

    /**
     * Calculate expected audio size for given parameters
     * @param {number} durationSeconds - Duration in seconds
     * @param {number} sampleRate - Sample rate (default: 44100)
     * @param {number} bitDepth - Bit depth (default: 16)
     * @param {number} channels - Channel count (default: 1)
     * @returns {number} Size in bytes
     */
    calculateAudioSize(durationSeconds, sampleRate = 44100, bitDepth = 16, channels = 1) {
        this._ensureInitialized();

        return this.module._calculateAudioSize(
            durationSeconds,
            sampleRate,
            bitDepth,
            channels
        );
    }

    /**
     * Convert audio samples to WAV format (client-side)
     * @param {Uint8Array} samples - PCM samples
     * @param {number} sampleRate - Sample rate
     * @param {number} bitDepth - Bit depth
     * @param {number} channels - Channel count
     * @returns {Blob} WAV file blob
     */
    samplesToWav(samples, sampleRate = 44100, bitDepth = 16, channels = 1) {
        const bytesPerSample = bitDepth / 8;
        const blockAlign = channels * bytesPerSample;
        const byteRate = sampleRate * blockAlign;
        const dataSize = samples.length;
        const fileSize = 44 + dataSize;

        // Create WAV buffer
        const buffer = new ArrayBuffer(fileSize);
        const view = new DataView(buffer);

        // Write WAV header
        const writeString = (offset, str) => {
            for (let i = 0; i < str.length; i++) {
                view.setUint8(offset + i, str.charCodeAt(i));
            }
        };

        writeString(0, 'RIFF');
        view.setUint32(4, fileSize - 8, true);
        writeString(8, 'WAVE');
        writeString(12, 'fmt ');
        view.setUint32(16, 16, true); // fmt chunk size
        view.setUint16(20, 1, true); // PCM format
        view.setUint16(22, channels, true);
        view.setUint32(24, sampleRate, true);
        view.setUint32(28, byteRate, true);
        view.setUint16(32, blockAlign, true);
        view.setUint16(34, bitDepth, true);
        writeString(36, 'data');
        view.setUint32(40, dataSize, true);

        // Write sample data
        const dataView = new Uint8Array(buffer, 44);
        dataView.set(samples);

        return new Blob([buffer], { type: 'audio/wav' });
    }

    /**
     * Create an Audio element from reconstructed samples
     * @param {Uint8Array} samples - PCM samples
     * @param {number} sampleRate - Sample rate
     * @param {number} bitDepth - Bit depth
     * @returns {HTMLAudioElement} Audio element ready to play
     */
    createAudioElement(samples, sampleRate = 44100, bitDepth = 16) {
        const wavBlob = this.samplesToWav(samples, sampleRate, bitDepth, 1);
        const url = URL.createObjectURL(wavBlob);
        const audio = new Audio(url);
        
        // Clean up object URL when audio is loaded
        audio.addEventListener('loadeddata', () => {
            URL.revokeObjectURL(url);
        });

        return audio;
    }
}

// Export for use in modules
export default AudioIndexWASM;

// Also make available globally for non-module scripts
if (typeof window !== 'undefined') {
    window.AudioIndexWASM = AudioIndexWASM;
}
